function anaglyphProcess(data,w,h,opts){
  opts=opts||{};
  var sep=opts.sep!=null?opts.sep:10;
  if(sep<0)sep=0; else if(sep>40)sep=40;
  var out=new Uint8ClampedArray(data.length);
  var half=sep/2;
  for(var y=0;y<h;y++) for(var x=0;x<w;x++){
    var xl=Math.max(0,Math.min(w-1,Math.round(x-half)));
    var xr=Math.max(0,Math.min(w-1,Math.round(x+half)));
    var p=(y*w+x)*4, pl=(y*w+xl)*4, pr=(y*w+xr)*4;
    // red from left eye, green+blue from right eye (classic red/cyan)
    out[p]=data[pl]; out[p+1]=data[pr+1]; out[p+2]=data[pr+2]; out[p+3]=data[p+3];
  }
  return out;
}

var EXPORTS={anaglyphProcess:anaglyphProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.AnaglyphForgePure = EXPORTS; }
